  <div class="left-panel">
    <!-- 标题和描述 -->
    <div class="panel-header">
      <h2 class="panel-title">{{ t('convertToVideo') }}</h2>
      <p class="panel-description">{{ t('describePromptGenerationVideo') }}</p>
    </div>

    <!-- 图片上传区域 - 使用UploadImage组件 -->
    <div class="upload-section">
      <div class="section-header">
        <h3 class="section-title">{{ t('uploadImages') }}</h3>
        <!-- <div class="toggle-container">
          <span class="toggle-label">{{ t('oneImage') }}</span>
          <el-switch 
            :model-value="formData.oneImageMode"
            @update:model-value="handleToggleChange"
            size="default"
            inactive-color="#E5E7EB"
            active-color="#E5E7EB"
          />
        </div> -->
      </div>
      <p class="section-description">{{ t('uploadImagesToGenerateVideo') }}</p>

      <!-- One Image 模式 - 单个图片上传 -->
      <div v-if="formData.oneImageMode" class="upload-container">
        <UploadImage
          width="100%"
          height="250px"
          :max-size="10"
          :need-compression="true"
          :default-url="formData.uploadedImages[0] ? formData.uploadedImageUrls[0] : ''"
          @uploadSuccess="(result) => handleUploadSuccess(result, 0)"
          @deleteSuccess="() => handleDeleteSuccess(0)"
        />
      </div>

      <!-- Two Images 模式 - 两个图片上传 -->
      <div v-else class="dual-upload-container">
        <!-- 第一个图片上传区域 -->
        <div class="upload-item">
          <UploadImage
            width="100%"
            height="150px"
