            :need-compression="true"
            :default-url="defaultImageUrls[0]"
            @uploadSuccess="(result) => handleUploadSuccess(result, 0)"
            @deleteSuccess="() => handleDeleteSuccess(0)"
          />
        </div>

        <!-- 第二个图片上传区域 -->
        <div class="upload-item">
          <UploadImage
            width="100%"
            height="150px"
            :max-size="10"
            :need-compression="true"
            @uploadSuccess="(result) => handleUploadSuccess(result, 1)"
            @deleteSuccess="() => handleDeleteSuccess(1)"
          />
        </div>
      </div>
    </div>

    <!-- 提示词输入 -->
    <div class="prompt-section">
      <h3 class="section-title">{{ t('prompt') }}</h3>
      <p class="section-description">{{ t('enterPromptToGenerateVideo') }}</p>
      
      <el-input
