      <div class="resolution-options">
        <div
          v-for="resolution in resolutionOptionsRef"
          :key="resolution.value"
          :class="['resolution-btn', { active: formData.resolution === resolution.value }]"
          @click="handleResolutionChange(resolution.value)"
          size="small"
        >
          {{ resolution.label }}
      </div>
      </div>
