      <div class="duration-options">
        <div
          v-for="duration in durationOptionsRef"
          :key="duration.value"
          :class="['duration-btn', { active: formData.duration === duration.value }]"
          @click="handleDurationChange(duration.value)"
          size="small"
        >
          {{ duration.label }}
      </div>
      </div>
    </div>

    <!-- 图片尺寸 - 使用RatioSelector组件 -->
    <div class="dimensions-section">
