        @expand-change="showMoreOptions = $event"
      />
    </div>

    <!-- 生成按钮 -->
    <div class="generate-section">
      <el-button
        type="primary"
        :disabled="isGenerateDisabled"
        :loading="isGenerating"
        @click="handleGenerate"
        class="generate-btn"
        :class="{disabled:isGenerateDisabled}"
        size="large"
      >
        <l-img src="/static/images/video-icon.png" w="22px" h="22px" />
        {{ t('generateVideo') }}
      </el-button>
