<script setup>
import { ref, reactive, computed, onMounted, onBeforeUnmount, onUnmounted } from 'vue';
import { useI18n } from 'vue-i18n';
import UploadImage from '@/components/upload/image.vue';
import OptionSelector from '@/components/business/components/option-selector.vue';
import RatioSelector from '@/components/business/components/ratio-selector.vue';
import OptionalSeedInput from '@/components/business/components/optional-seed-input.vue';
import LImg from '@/components/l-img.vue';
import { resolutionOptions, durationOptions, calculateResolution } from '@/types/panel-options';
import { useMediaGenerationStore } from '@/store/modules/media-generation';
import { addTaskToPolling, TaskType } from '@/presenter/media-task-polling';
import { mediaTaskEventBus, clearMediaTaskEventListeners } from '@/presenter/media-task-events';
import router from '@/router';
import { IMAGE_OPERATIONS } from '@/types/media-tool';
import { apiGeneration } from '@/api/api-generation';

const { t } = useI18n();
const mediaStore = useMediaGenerationStore();


// 当前模块的 key
const MODULE_KEY = IMAGE_OPERATIONS.TO_VIDEO;

// 内部数据管理
const isGenerating = ref(false);
const isRandoming = ref(false);
const showMoreOptions = ref(false);
// 当前任务ID，用于事件过滤
const currentTaskId = ref(null);

// 获取存储的生成结果
const loadGenerationResult = () => {
  const result = mediaStore.getGenerationResult(MODULE_KEY);
  if (result) {
    // 设置默认图片URL
    if (result.imageUrls && Array.isArray(result.imageUrls)) {
      formData.uploadedImageUrls = [...result.imageUrls];
      // 为每个URL创建对应的文件标识
      formData.uploadedImages = result.imageUrls.map(() => ({ name: 'from-previous-generation' }));
    } else if (result.imageUrl) {
      // 设置图片URL和文件标识
      formData.uploadedImageUrls = [result.imageUrl];
      formData.uploadedImages = [{ name: 'from-previous-generation' }];
    }
  }
};


// 清除生成结果
const clearGenerationResult = () => {
  mediaStore.clearGenerationResult(MODULE_KEY);
};

const formData = reactive({
  oneImageMode: true,
  uploadedImages: [],
  uploadedImageUrls: [],
  uploadedImageDimensions: [],
  prompt: '',
  model: '',
  resolution: '',
  duration: '',
  dimensions: '',
  seed: ''
});

// Emits定义 - 只发送四个状态事件
const emit = defineEmits(['generate-success', 'generate-error', 'generate-create', 'loading']);

const resolutionOptionsRef = ref(resolutionOptions);

// 时长选项
const durationOptionsRef = ref(durationOptions);

// 计算属性
const defaultImageUrls = computed(() => {
  return [
    formData.uploadedImages[0] ? formData.uploadedImageUrls[0] : '',
    formData.uploadedImages[1] ? formData.uploadedImageUrls[1] : ''
  ];
});

const isGenerateDisabled = computed(() => {
  if (formData.oneImageMode) {
    return !formData.uploadedImageUrls[0] || !formData.prompt.trim() || !formData.model || !formData.resolution || !formData.duration || !formData.dimensions;
  } else {
    return (!formData.uploadedImageUrls[0] && !formData.uploadedImageUrls[1]) || !formData.prompt.trim() || !formData.model || !formData.resolution || !formData.duration || !formData.dimensions;
  }
});

// 方法
const handleToggleChange = (value) => {
  formData.oneImageMode = value;
  
  // 如果切换到单图模式，只保留第一张图片
  if (value && formData.uploadedImages.length > 1) {
    formData.uploadedImages = [formData.uploadedImages[0]];
    formData.uploadedImageUrls = [formData.uploadedImageUrls[0]];
    formData.uploadedImageDimensions = [formData.uploadedImageDimensions[0]];
  }
};

// 处理图片上传成功 - UploadImage组件事件
const handleUploadSuccess = (result, index) => {
  // 确保数组有足够的长度
  while (formData.uploadedImages.length <= index) {
    formData.uploadedImages.push(null);
    formData.uploadedImageUrls.push('');
    formData.uploadedImageDimensions.push(null);
  }

  formData.uploadedImages[index] = result.originalFile;
  formData.uploadedImageUrls[index] = result.url;
  formData.uploadedImageDimensions[index] = result.dimensions;
};

// 处理图片删除成功 - UploadImage组件事件
const handleDeleteSuccess = (index) => {
  formData.uploadedImages[index] = null;
  formData.uploadedImageUrls[index] = '';
  formData.uploadedImageDimensions[index] = null;
};

const generateRandomPrompt = () => {
  isRandoming.value = true;
  setTimeout(() => {
    isRandoming.value = false;
  }, 1000);
  const randomPrompts = [
    'A peaceful ocean waves gently moving',
    'Clouds slowly drifting across a blue sky',
    'Autumn leaves falling in slow motion',
    'A cat stretching and yawning',
    'Smoke rising from a coffee cup'
  ];
  const randomPrompt = randomPrompts[Math.floor(Math.random() * randomPrompts.length)];
  formData.prompt = randomPrompt;
};

const handleResolutionChange = (value) => {
  formData.resolution = value;
};

const handleDurationChange = (value) => {
  formData.duration = value;
};

const handlePromptChange = (value) => {
  formData.prompt = value;
};

// 根据清晰度和尺寸比例计算分辨率 - 简化版本
const getResolutionFromParams = (resolution, dimensions) => {
  return calculateResolution(resolution || 'hd', dimensions || '16:9', 'video');
};

// 处理任务完成事件
const handleTaskCompleted = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    emit('generate-success', res);
    isGenerating.value = false;
    currentTaskId.value = null;
  }
};

// 处理任务失败事件
const handleTaskFailed = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    emit('generate-error', res);
    isGenerating.value = false;
    currentTaskId.value = null;
  }
};

// 处理任务状态更新事件
const handleTaskStatusUpdate = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    // 更新进度等信息
    console.log(`Text-to-image-to-video progress: ${res.res.progress}%`);
    emit('loading', true, res.res.estimated_time || null);
  }
};


// 处理生成按钮点击
const handleGenerate = async () => {
  try {
    emit('generate-create');
    emit('loading', true, null);
    isGenerating.value = true;
    const baseUrl = process.env.VITE_APP_OSS_PIC_PATH;
    
    
    // 准备请求数据，映射到API期望的格式
    // 注意：保持表单验证逻辑不变，但API只发送必要字段
    const requestData = {
      source_image_url: baseUrl+formData.uploadedImageUrls[0],
      prompt: formData.prompt.trim(),
      model: formData.model,
      duration: parseInt(formData.duration),
      aspect_ratio: formData.dimensions,
      negative_prompt: '' // 固定传空字符串
    };

    console.log('Image-to-video generating with data:', requestData);
    
    // 调用真实的API
    const apiResult = await apiGeneration.imageToVideo(requestData);
    
    // 设置路由meta并添加到轮询管理器
    const meta = router.currentRoute.value.meta;
    meta.taskId = apiResult.task_id;
    meta.type = TaskType.VIDEO;
    addTaskToPolling(apiResult.task_id, TaskType.VIDEO);
    
    // 设置当前任务ID
    currentTaskId.value = apiResult.task_id;
    
  } catch (error) {
    emit('loading', false,null);
    isGenerating.value = false;
    emit('generate-error', error);
  }
};

// 生命周期钩子
onMounted(() => {
  // 获取之前保存的生成结果
  loadGenerationResult();
  
  // 绑定媒体任务事件监听器（只绑定一次）
  mediaTaskEventBus.on('task-completed', handleTaskCompleted);
  mediaTaskEventBus.on('task-failed', handleTaskFailed);
  mediaTaskEventBus.on('task-status-update', handleTaskStatusUpdate);
});

// 组件卸载前清理生成结果
onBeforeUnmount(() => {
  clearGenerationResult();
  // 清理事件监听器（只清理一次）
  clearMediaTaskEventListeners();
});
</script>

